SET plan_cache_mode=force_custom_plan; SET statement_timeout=120000; PREPARE hfs1579 AS SELECT id, version_id, data, last_updated, fhir_version, last_updated AS sort_key FROM resources WHERE tenant_id = $1 AND resource_type = $2 AND is_deleted = FALSE AND (EXISTS (WITH referenced_observations AS MATERIALIZED (SELECT patient.resource_id AS id FROM search_index patient WHERE patient.tenant_id = resources.tenant_id AND patient.resource_type = 'Observation' AND patient.param_name = 'patient' AND patient.is_contained = FALSE AND patient.value_reference = 'Patient/' || resources.id) SELECT 1 FROM referenced_observations source WHERE EXISTS (SELECT 1 FROM resources observation WHERE observation.tenant_id = resources.tenant_id AND observation.resource_type = 'Observation' AND observation.id = (WITH scoped_code AS MATERIALIZED (SELECT resource_id, value_token_system, value_token_code FROM search_index WHERE tenant_id = resources.tenant_id AND resource_type = 'Observation' AND resource_id = source.id AND param_name = 'code' AND is_contained = FALSE) SELECT resource_id FROM scoped_code WHERE value_token_system IN ($3, 'urn:x-helios:implicit code system') AND value_token_code = $4 LIMIT 1) AND observation.is_deleted = FALSE AND observation.data #>> '{subject,reference}' = 'Patient/' || resources.id))) ORDER BY last_updated DESC, id ASC LIMIT 6;
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) EXECUTE hfs1579('default','Patient','http://loinc.org','8302-2');
